actions.script:
from = from || 'now-7d';thru = thru || 'now'
const base = {datasetId,from,thru,queryString:queryString || '',filters:JSON.parse(filtersJson || '[]')}
const anchorResult = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters(Object.assign({},base,{
    query:{bool:{all:[{field:{name:'_document',op:'eq',value:documentType}},{field:{name:'_id',op:'eq',value:documentId}}]}},pageSize:1
})).call()
const anchor = (anchorResult.hits || [])[0]
contextLines = [];contextNotice = ''
if (!anchor) contextNotice = 'This entry is unavailable in the authorized dataset and time range.'
else {
    const field = anchorResult.dataset.timeField
    const values = [anchor.body[field],anchor.documentId+':'+anchor.id]
    const before = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters(Object.assign({},base,{
        sort:['-'+field,'-__cursor'],cursor:{datasetId,sort:['-'+field,'-__cursor'],values},pageSize:25
    })).call()
    const after = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters(Object.assign({},base,{
        sort:[field,'__cursor'],cursor:{datasetId,sort:[field,'__cursor'],values},pageSize:25
    })).call()
    contextLines = [...(before.hits || []).reverse(),anchor,...(after.hits || [])].map(hit=>({
        timestamp:hit.body[field],level:hit.body.severity_text || '',message:String(hit.body.body || hit.body.name || ''),
        traceId:hit.body.trace_id || '',selected:hit.id===anchor.id && hit.documentId===anchor.documentId ? '→' : '',
        documentJson:JSON.stringify(hit.body,null,2)
    }))
}
